// Canvas setup
const canvas = document.querySelector("canvas");
const context = canvas.getContext("2d");

// Initialize canvas dimensions to match window
function setCanvasDimensions() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
setCanvasDimensions();

// Mouse tracking
const mouse = {
  x: undefined,
  y: undefined
};

// Configuration constants
const MAX_RADIUS = 40;            // Maximum size when circle is near mouse
const MIN_RADIUS = 1;             // Minimum circle size
const MAX_CIRCLES = 1300;          // Total number of circles
const MOUSE_INTERACTION_RANGE = 60; // How close mouse needs to be to affect circles
const COLORS = ["#B22F3E", "#FFFA77", "#FF5D70", "#369BCC", "#023852"];

// Track mouse movement
window.addEventListener("mousemove", (event) => {
  mouse.x = event.x;
  mouse.y = event.y;
});

// Handle window resize
window.addEventListener("resize", () => {
  setCanvasDimensions();
  createCircles();
});

/**
 * Creates a circle object with drawing and update capabilities
 * @param {number} x - Initial x position
 * @param {number} y - Initial y position
 * @param {number} dx - Velocity in x direction
 * @param {number} dy - Velocity in y direction
 * @param {number} radius - Initial radius
 */
function createCircle(x, y, dx, dy, radius) {
  const initialRadius = radius;
  const color = COLORS[Math.floor(Math.random() * COLORS.length)];

  /**
   * Draws the circle on the canvas
   */
  function draw() {
    context.beginPath();
    context.arc(x, y, radius, 0, Math.PI * 2, false);
    context.fillStyle = color;
    context.fill();
    
    // Add subtle border to circles
    context.strokeStyle = "#333";
    context.lineWidth = 0.5;
    context.stroke();
  }

  /**
   * Updates circle position and handles collisions/interactions
   */
  function update() {
    // Handle wall collisions
    if (x + radius > innerWidth || x - radius < 0) {
      dx = -dx;
    }
    if (y + radius > innerHeight || y - radius < 0) {
      dy = -dy;
    }

    // Update position
    x += dx;
    y += dy;

    // Handle mouse interaction
    const distanceX = mouse.x - x;
    const distanceY = mouse.y - y;
    const isNearMouse = Math.abs(distanceX) < MOUSE_INTERACTION_RANGE && 
                       Math.abs(distanceY) < MOUSE_INTERACTION_RANGE;

    if (isNearMouse && radius < MAX_RADIUS) {
      radius += 1;
    } else if (radius > initialRadius) {
      radius -= 1;
    }

    draw();
  }

  return { draw, update };
}

// Circle management
let circles = [];

/**
 * Creates all circles and populates the circles array
 */
function createCircles() {
  circles = [];
  
  for (let i = 0; i < MAX_CIRCLES; i++) {
    const radius = Math.random() * 5 + MIN_RADIUS;
    const x = Math.random() * (innerWidth - radius * 2) + radius;
    const y = Math.random() * (innerHeight - radius * 2) + radius;
    const dx = (Math.random() - 0.5) * 1;
    const dy = (Math.random() - 0.5) * 1;
    
    circles.push(createCircle(x, y, dx, dy, radius));
  }
}

/**
 * Animation loop that clears and redraws the canvas
 */
function animate() {
  requestAnimationFrame(animate);
  context.clearRect(0, 0, innerWidth, innerHeight);
  
  circles.forEach(circle => circle.update());
}

// Start the animation
createCircles();
animate();
